module Rerun

# Raw C bindings (generated by gen/generator.jl from the rerun_c headers).
include(joinpath(@__DIR__, "..", "gen", "LibRerunC.jl"))

# Resolved Arrow datatype model + the generated component/archetype catalog
# (generated by gen/gen_schemas.jl from the vendored Rerun IDL).
include(joinpath(@__DIR__, "arrow_types.jl"))
include(joinpath(@__DIR__, "generated_schemas.jl"))
include(joinpath(@__DIR__, "arrow_schema.jl"))    # ArrowType <-> C Data Interface schema structs

# Julia-side abstraction layers.
include(joinpath(@__DIR__, "errors.jl"))      # RerunError + checked()
include(joinpath(@__DIR__, "marshal.jl"))     # rr_string / rr_bytes marshalling
include(joinpath(@__DIR__, "time.jl"))        # TimePoint + Timeline (canonical time representations)
include(joinpath(@__DIR__, "cdata.jl"))       # Arrow C Data Interface export
include(joinpath(@__DIR__, "stream.jl"))      # RecordingStream + string-based log
include(joinpath(@__DIR__, "sinks.jl"))       # LogSink sum type + set_sinks
include(joinpath(@__DIR__, "types.jl"))       # Component/Archetype tags + typed log
include(joinpath(@__DIR__, "interop.jl"))     # component/wire_compatible traits + materialization
include(joinpath(@__DIR__, "columns.jl"))     # send_columns (columnar/temporal bulk)
include(joinpath(@__DIR__, "util.jl"))        # entity-path escaping, video timestamps
include(joinpath(@__DIR__, "generated_types.jl"))  # generated component/archetype structs
include(joinpath(@__DIR__, "helpers.jl"))     # high-level conveniences (log_tensor, ...)
include(joinpath(@__DIR__, "query.jl"))       # dataframe query (read data out) -> Tables.jl

"""Resolved Arrow datatype for a Rerun component, e.g. `"rerun.components.Position3D"`."""
component_arrow_type(ct::AbstractString) = COMPONENT_TYPES[ct]

"""Field descriptors for a Rerun archetype, e.g. `"rerun.archetypes.Points3D"`."""
archetype_fields(a::AbstractString) = ARCHETYPES[a]

"""Human-readable version string of the linked rerun_c SDK."""
version() = unsafe_string(LibRerunC.rr_version_string())

function __init__()
    _init_callbacks()        # array release callbacks (cdata.jl)
    _init_schema_release()   # schema release callback (arrow_schema.jl)
    return
end

export RecordingStream, RerunError, LogSink, GrpcSink, FileSink, TimeColumn, Timeline, TimePoint

# The unexported public API, accessed as `Rerun.f(...)`. The `public` keyword
# parses on Julia ≥ 1.11 only, so it is evaluated behind a version gate.
@static if VERSION >= v"1.11"
    eval(Meta.parse("public " * join([
        # stream lifecycle + sinks
        "is_enabled", "save", "connect_grpc", "spawn", "serve_grpc", "to_stdout",
        "set_sinks", "set_global!", "set_thread_local!", "SpawnOptions",
        # time
        "set_time", "reset_time", "disable_timeline", "kind",
        # logging
        "log", "log_archetype", "log_tensor", "log_file", "log_file_contents",
        "send_columns", "columns",
        # interop traits
        "component", "wire_compatible", "InteropError",
        # queries
        "load_recording", "Recording", "timelines", "timeline", "view",
        "RecordingView", "set_contents!", "filter_range", "fill_latest_at",
        "select", "QueryResult", "ArrowColumn",
        # introspection + utilities
        "version", "component_arrow_type", "archetype_fields",
        "escape_entity_path_part", "video_frame_timestamps_nanos",
        # generated catalogs
        "Components", "Archetypes", "Blueprint",
    ], ", ")))
end

end # module Rerun
